test('lost team-save responses retry with the same nonce and do not duplicate team revisions or changes',async()=>{
 const f=await fixture();try{f.$('[data-career-section="teams"]').click();await tick();f.$('[data-career-team="loud"]').click();await tick();f.$('[data-team-tab="profile"]').click();await tick();const form=f.$('#career-team-form');form.elements.short.value='LLL';const original=f.w.careerAdmin;let lost=true;f.w.careerAdmin=async(...args)=>{const result=await original(...args);if(args[1]==='saveTeam'&&lost){lost=false;throw Error('Conexão interrompida');}return result;};form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.match(f.$('#career-team-message').textContent,/Conexão interrompida/);assert(!form.querySelector('[type=submit]').disabled);form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();const calls=f.calls.filter(c=>c.operation==='saveTeam');assert.equal(calls.length,2);assert.equal(calls[0].body.nonce,calls[1].body.nonce);assert.equal(f.core.publicRead('team',{name:'LOUD',metadata:'1'}).team.revision,2);assert.equal((await f.core.admin({uid:'admin',admin:true},{operation:'teamHistory',teamId:'loud'})).entries.length,1);}finally{f.close();}
});
test('a lost new-team passage response reuses the original confirmation and team name even after that team now exists',async()=>{
 const f=await fixture();try{f.$('[data-career-person="p0"]').click();await tick();f.$('[data-career-new-tenure]').click();const form=f.$('#career-tenure-form');form.elements.teamName.value='Equipe nova retry';form.elements.status.value='active';const original=f.w.careerAdmin;let lost=true;f.w.careerAdmin=async(...args)=>{const result=await original(...args);if(args[1]==='saveTenure'&&lost){lost=false;throw Error('Resposta perdida');}return result;};form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.match(f.$('#career-editor-message').textContent,/Resposta perdida/);assert(!form.querySelector('[type=submit]').disabled);form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert(!f.$('#career-editor').open);const calls=f.calls.filter(c=>c.operation==='saveTenure');assert.equal(calls.length,2);assert.deepEqual(calls[0].body,calls[1].body);assert.equal(f.core.publicRead('person',{id:'p0'}).person.tenures.length,1);}finally{f.close();}
});

test('market tab is lazy, preserves a private draft and publishes without reading the whole catalogue',async()=>{const f=await fixture();try{assert(!f.calls.some(c=>c.operation.startsWith('market')));f.$('[data-career-market-tab]').click();await tick();assert(f.$('.career-workspace').hidden);assert.equal(f.calls.filter(c=>c.operation==='marketList').length,1);f.$('[data-market-new]').click();let form=f.$('#market-editor form');form.elements.name.value='Duas pessoas, Outro nome';form.elements.toName.value='LOUD';form.elements.date.value='2026-10-14';form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.equal(f.$('#market-editor').open,false);assert.equal(f.core.publicRead('market',{}).total,0);assert(f.$('[data-market-list]').textContent.includes('Duas pessoas'));f.$('[data-market-edit]').click();form=f.$('#market-editor form');form.elements.publication.value='published';form.elements.status.value='fechado';form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.equal(f.core.publicRead('market',{}).total,1);assert.equal(f.core.publicRead('market',{}).entries[0].jogador,'Duas pessoas, Outro nome');assert.equal(f.calls.filter(c=>c.operation==='person').length,0);f.$('[data-career-section=teams]').click();await tick();assert(f.$('#career-market-panel').hidden);assert(!f.$('.career-workspace').hidden);}finally{f.close();}});
test('market picker fetches one selected career, applies a confirmed arrival and can archive its public card',async()=>{const f=await fixture();try{f.$('[data-career-market-tab]').click();await tick();f.$('[data-market-new]').click();let form=f.$('#market-editor form');form.elements.name.value='Jogador 00';form.elements.name.dispatchEvent(new f.w.Event('input',{bubbles:true}));await new Promise(r=>setTimeout(r,340));await tick();assert(f.$('[data-market-person-pick]'));f.$('[data-market-person-pick]').click();await tick();assert.equal(f.calls.filter(c=>c.operation==='person').length,1);assert(form.elements.personId.value);form.elements.toName.value='LOUD';form.elements.date.value='2026-10-14';form.elements.publication.value='published';form.elements.status.value='fechado';form.elements.applyCareer.checked=true;form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.equal(f.$('#market-editor').open,false);assert.equal(f.core.publicRead('person',{id:'p0'}).person.current[0].teamName,'LOUD');f.$('[data-market-edit]').click();await tick();form=f.$('#market-editor form');assert(form.elements.applyCareer.disabled);form.elements.publication.value='archived';form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.equal(f.core.publicRead('market',{}).total,0);assert.equal(f.core.publicRead('person',{id:'p0'}).person.current.length,1);}finally{f.close();}});
test('career editor can publish the same confirmed move and market resets private content after logout',async()=>{const f=await fixture();try{f.$('[data-career-person="p0"]').click();await tick();f.$('[data-career-new-tenure]').click();const form=f.$('#career-tenure-form');form.elements.teamName.value='LOUD';form.elements.status.value='active';form.elements.startDate.value='2026-10-14';form.elements.publishMarket.checked=true;form.dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert.equal(f.core.publicRead('market',{}).total,1);f.$('[data-career-market-tab]').click();await tick();assert(f.$('[data-market-list]').textContent.includes('Aplicada à carreira'));f.$('[data-market-edit]').click();await tick();f.auth.currentUser=null;f.w.__authChange(null);assert(!f.$('#market-editor').open);assert(!f.$('#market-editor').textContent);assert(!f.$('#career-market-panel').textContent);}finally{f.close();}});
test('the existing team exits can be selected and exported from Mercado without reopening each player',async()=>{const f=await fixture();try{const p=(await f.core.admin({admin:true,uid:'admin'},{operation:'saveTenure',personId:'p0',revision:1,nonce:crypto.randomUUID(),tenure:{teamId:'loud',role:'player',status:'active',start:{date:'2021-01-19'},end:{}}})).person;await f.core.admin({admin:true,uid:'admin'},{operation:'releasePerson',personId:p.id,revision:p.revision,nonce:crypto.randomUUID(),tenureIds:p.current.map(t=>t.id),departure:{date:'2026-10-14'},reason:'Equipe pausou'});f.$('[data-career-market-tab]').click();await tick();f.$('[data-market-export]').click();const dialog=f.$('#market-export-departures');dialog.querySelector('[name=teamName]').value='LOUD';dialog.querySelector('[data-export-search]').click();await tick();assert(dialog.textContent.includes('Jogador 00'));assert(dialog.textContent.includes('Sem equipe / F/A'));dialog.querySelector('[data-export-select-page]').click();assert.equal(dialog.querySelector('[data-export-submit]').disabled,false);dialog.querySelector('form').dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true}));await tick();assert(!dialog.open);assert.equal(f.core.publicRead('market',{}).total,1);assert.equal(f.core.publicRead('person',{id:'p0'}).person.availability,'free_agent');assert(f.$('#career-market-panel').textContent.includes('1 saída(s) exportada(s)'));assert.equal(f.calls.filter(c=>c.operation==='person').length,0);f.$('[data-market-export]').click();dialog.querySelector('[name=teamName]').value='LOUD';dialog.querySelector('[data-export-search]').click();await tick();assert(!dialog.querySelector('[data-export-choice]').disabled);dialog.querySelector('[name=grouped]').checked=false;dialog.querySelector('[name=grouped]').dispatchEvent(new f.w.Event('change',{bubbles:true}));await tick();assert(dialog.querySelector('[data-export-choice]').disabled);assert(dialog.textContent.includes('Já está no Mercado'));}finally{f.close();}});
test('the team page opens the export preview with its team prefilled and the dialog clears on logout',async()=>{const f=await fixture();try{f.$('[data-career-section=teams]').click();await tick();f.$('[data-career-team]').click();await tick();f.$('[data-team-market-export]').click();await tick();assert(f.$('#market-export-departures').open);assert.equal(f.$('#market-export-departures [name=teamName]').value,'LOUD');assert.equal(f.calls.filter(c=>c.operation==='marketDepartureCandidates').length,1);f.auth.currentUser=null;f.w.__authChange(null);assert(!f.$('#market-export-departures').open);assert.equal(f.$('#market-export-departures').textContent,'');}finally{f.close();}});

test('market delete button confirms the selected card, removes it from the list and public feed, and preserves careers',async()=>{const f=await fixture();try{await f.core.admin({uid:'admin',admin:true},{operation:'marketSave',nonce:crypto.randomUUID(),entry:{name:'Elenco',fromName:'LOUD',toName:'Sem equipe / F/A',status:'fechado',publication:'published'}});const before=f.core.publicRead('person',{id:'p0'});f.$('[data-career-market-tab]').click();await tick();assert(f.$('[data-market-delete]'));let confirmed='';f.w.confirm=text=>(confirmed=text,false);f.$('[data-market-delete]').click();await tick();assert.equal(f.core.publicRead('market',{}).total,1);f.w.confirm=text=>(confirmed=text,true);f.$('[data-market-delete]').click();await tick();assert(confirmed.includes('Elenco'));assert(!f.$('[data-market-delete]'));assert.equal(f.core.publicRead('market',{}).total,0);assert.deepEqual(f.core.publicRead('person',{id:'p0'}),before);assert(f.$('#career-market-panel').textContent.includes('Movimentação excluída'));}finally{f.close();}});
